    },
    "multiline": {
      "type": "boolean",
      "description": "Enable multiline mode where patterns can span lines."
    }
  },
  "required": [
    "pattern"
  ]
}
```
- BrowserScreenshot
```json
{
  "type": "object",
  "properties": {
    "url": {
      "type": "string",
      "description": "The URL to navigate to and capture."
    },
    "wait_seconds": {
      "type": "number",
      "description": "Total observation time in seconds (default: 2.0).",
      "default": 2.0
    },
    "frame_count": {
      "type": "integer",
      "description": "Number of screenshots to capture (default: 4).",
      "default": 4
    }
  },
  "required": [
    "url"
  ]
}
```
- ReadMedia
```json
{
  "type": "object",
  "properties": {
    "path": {
      "type": "string",
      "description": "Path to the video file."
    },
    "media_type": {
